def render_html(result):
    """Render the workspace shell bound only to its original project identity."""
    bootstrap = json.dumps({"project_identity": result["project_identity"]}, ensure_ascii=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    html = _HTML.replace("__BOOTSTRAP__", bootstrap)
    script = html.split("<script>", 1)[1].split("</script>", 1)[0]
    style = html.split("<style>", 1)[1].split("</style>", 1)[0]
    sha = lambda value: base64.b64encode(hashlib.sha256(value.encode("utf-8")).digest()).decode("ascii")
    policy = "default-src 'none'; script-src 'sha256-"+sha(script)+"'; style-src 'sha256-"+sha(style)+"'; connect-src 'self'; base-uri 'none'; form-action 'none'"
    return html.replace('<meta name="viewport"', '<meta http-equiv="Content-Security-Policy" content="'+policy+'"><meta name="viewport"', 1)
